<?php /** @var array<string,mixed> $p */ /** @var list<array<string,mixed>> $history */ /** @var list<array<string,mixed>> $notes */ /** @var list<array<string,mixed>> $allocations */ /** @var ?array<string,int> $balance */
/** @var bool $canApprove */ /** @var bool $canRecord */ /** @var ?array<string,mixed> $details */ use Vertex\Core\View; $url = '/payouts/' . $p['public_id']; $st = $p['status']; ?>
<div class="page-head"><div><p class="eyebrow">Payout request</p><h1><?= e($p['reference']) ?></h1></div><a class="btn btn-ghost" href="/payouts">&larr; Payouts</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('pbadge', ['kind' => 'payout', 's' => $st]) ?></div><div><span class="muted">Requested amount</span><br><strong><?= e(money($p['amount_minor'])) ?></strong></div>
    <div><span class="muted">Balance when requested</span><br><?= e(money($p['available_minor'])) ?></div><?php if ($balance) : ?><div><span class="muted">Free balance now</span><br><?= e(money($balance['available'])) ?></div><?php endif; ?></div>
    <dl class="detail-list"><dt>Partner</dt><dd><a href="/referrals/partners/<?= e($p['partner_public_id']) ?>"><?= e($p['partner_name']) ?></a></dd><dt>Requested</dt><dd><?= e(local_time($p['requested_at'])) ?></dd>
        <dt>Payout details</dt><dd><?= $p['details_hint'] ? e($p['details_hint']) : 'none on file' ?> <span class="muted">(stored encrypted)</span></dd>
        <?php if ($p['partner_notes']) : ?><dt>Partner's notes</dt><dd class="prewrap"><?= e($p['partner_notes']) ?></dd><?php endif; ?><?php if ($p['reason']) : ?><dt>Message / reason</dt><dd class="prewrap"><?= e($p['reason']) ?></dd><?php endif; ?>
        <?php if ($p['approved_at']) : ?><dt>Approved</dt><dd><?= e($p['approved_by_name'] ?? '') ?> · <?= e(local_time($p['approved_at'])) ?></dd><?php endif; ?>
        <?php if ($p['paid_at']) : ?><dt>Paid</dt><dd><?= e(money($p['paid_amount_minor'])) ?> · <?= e(config("referrals.payment_methods.{$p['payment_method']}", $p['payment_method'])) ?> · <?= e(local_date($p['payment_date'])) ?> · reference <?= e($p['payment_reference']) ?><br><span class="muted">Recorded by <?= e($p['paid_by_name'] ?? '') ?> · <?= e(local_time($p['paid_at'])) ?></span></dd><?php endif; ?></dl>
    <p class="muted">Approving a payout is not paying it. A payout is Paid only when someone with the payment-recording permission records the actual transfer.</p></div>
<?php if ($allocations !== []) : ?><div class="panel"><h2>Commission reserved by this request</h2><div class="table-wrap"><table class="table"><thead><tr><th>Entry</th><th>Milestone</th><th class="num">Reserved</th><th>State</th></tr></thead><tbody>
    <?php foreach ($allocations as $a) : ?><tr><td><?= e($a['reference']) ?></td><td><?= e(config("referrals.milestone_labels.{$a['milestone']}", $a['milestone'])) ?></td><td class="num"><?= e(money($a['amount_minor'])) ?></td><td><?= $a['released_at'] ? 'Released' : 'Reserved' ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php if ($canApprove && in_array($st, ['requested', 'under_review'], true)) : ?><div class="panel"><h2>Review</h2>
    <?php if ($st === 'requested') : ?><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="review"><button class="btn btn-ghost btn-sm" type="submit">Move to Under Review</button></form><?php endif; ?>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Approve this payout? Nothing is paid yet."><?= csrf_field() ?><input type="hidden" name="action" value="approve"><p class="muted">The commission ledger and the partner's free balance are re-verified when you approve.</p>
        <div class="field"><label for="an">Note (optional)</label><input id="an" name="note" maxlength="500"></div><div class="field"><label for="apw">Your password</label><input id="apw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Approve</button></div></form>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="reject"><div class="field"><label for="rr">Rejection reason (the partner will read this)</label><textarea id="rr" name="reason" rows="2" required minlength="10" maxlength="500"></textarea></div>
        <div class="form-actions"><button class="btn btn-danger btn-sm" type="submit">Reject and release the amount</button></div></form></div><?php endif; ?>
<?php if ($canRecord && $st === 'approved') : ?><div class="panel"><h2>Processing</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="processing"><button class="btn btn-ghost btn-sm" type="submit">Mark as processing</button></form></div><?php endif; ?>
<?php if ($canRecord && in_array($st, ['approved', 'processing'], true)) : ?><div class="panel"><h2>Payout details</h2>
    <?php if ($details) : ?><p class="muted">Shown to you because you are recording this payment. This view is audited.</p><dl class="detail-list"><?php foreach ($details as $k => $val) : ?><dt><?= e(str_replace('_', ' ', (string) $k)) ?></dt><dd><?= e((string) $val) ?></dd><?php endforeach; ?></dl>
    <?php else : ?><a class="btn btn-ghost btn-sm" href="<?= e($url) ?>?reveal=1">Reveal payout details (audited)</a><?php endif; ?></div>
    <div class="panel"><h2>Record the payment</h2><p class="muted">Record only a transfer that has actually been made. The amount must equal the approved amount (<?= e(money($p['amount_minor'])) ?>).</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Record this payment? This marks the payout as Paid."><?= csrf_field() ?><input type="hidden" name="action" value="pay">
        <div class="field"><label for="pm">Method</label><select id="pm" name="method" required><?php foreach (config('referrals.payment_methods') as $c => $l) : ?><option value="<?= e($c) ?>"<?= old('method') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="pr">Transaction reference</label><input id="pr" name="reference" required maxlength="120" value="<?= e(old('reference')) ?>"></div><div class="field"><label for="pd">Payment date</label><input id="pd" name="date" type="date" required value="<?= e(old('date')) ?>"></div>
        <div class="field"><label for="pa">Amount paid (₹)</label><input id="pa" name="amount" required inputmode="decimal" value="<?= e(old('amount', number_format((int) $p['amount_minor'] / 100, 2, '.', ''))) ?>"></div><div class="field"><label for="pn">Note (optional)</label><input id="pn" name="note" maxlength="255"></div>
        <div class="field"><label for="pw">Your password</label><input id="pw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Record payment</button></div></form></div><?php endif; ?>
<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($history as $h) : ?><li><strong><?= e(config("referrals.payout_statuses.{$h['to_status']}", $h['to_status'])) ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?> · <?= e($h['actor'] ?? 'system') ?><?= $h['visibility'] === 'internal' ? ' · internal' : '' ?></span><?php if ($h['note']) : ?><p class="prewrap"><?= e($h['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div>
<div class="panel"><h2>Internal notes <span class="badge badge-sensitive">staff only</span></h2>
    <?php foreach ($notes as $n) : ?><div class="note"><p class="prewrap"><?= e($n['body']) ?></p><p class="muted"><?= e($n['author'] ?? '') ?> · <?= e(local_time($n['created_at'])) ?></p></div><?php endforeach; ?><?php if ($notes === []) : ?><p class="muted">No notes.</p><?php endif; ?>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="note"><div class="field"><label for="nb">Add a note</label><textarea id="nb" name="body" rows="2" required maxlength="3000"></textarea></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Add note</button></div></form></div>
